{
  "hooks": {
    "PostToolUse": [
      {
        "id": "after-read",
        "matcher": "Read",
        "command": "sed \"s#$PWD#WS#g\" >> .hooklog; echo 'lint: nothing to report'"
      },
      {
        "id": "after-write",
        "matcher": "Write",
        "command": "sed \"s#$PWD#WS#g\" >> .hooklog; echo 'lint failed: trailing whitespace' >&2; exit 2"
      },
      {
        "id": "after-edit",
        "matcher": "Edit",
        "command": "sed \"s#$PWD#WS#g\" >> .hooklog; echo 'should never run'"
      },
      {
        "id": "disabled",
        "enabled": false,
        "matcher": "Read",
        "command": "sed \"s#$PWD#WS#g\" >> .hooklog; echo 'disabled hook ran'"
      }
    ]
  }
}

